std::set<std::string> unique_identifiers;

// STRENGTH: Automatic uniqueness and ordering
unique_identifiers.insert("Alpha");
unique_identifiers.insert("Beta");
unique_identifiers.insert("Alpha"); // Duplicate ignored

// STRENGTH: Lookup, Insertion, Deletion: O(log N)
auto it = unique_identifiers.find("Beta");

// WEAKNESS: High memory/cache overhead (tree nodes)
// WEAKNESS: Slower than std::unordered_set (O(log N) vs O(1) avg)
//          if order preservation is not needed.

size_t count = unique_identifiers.size(); // count = 2
